package com.hotel.controller;
import com.hotel.dao.impl.FrontDeskDaoImpl;import com.hotel.exception.DataAccessException;import com.hotel.service.FrontDeskService;import com.hotel.service.impl.FrontDeskServiceImpl;import com.hotel.util.DBConnection;import jakarta.servlet.*;import jakarta.servlet.annotation.WebServlet;import jakarta.servlet.http.*;import java.io.*;
/** UC30 is read-only selection assistance. Assignments are persisted only by UC28. */
@WebServlet("/receptionist/rooms/assign")public class AssignRoomServlet extends HttpServlet{private final FrontDeskService service=new FrontDeskServiceImpl(new FrontDeskDaoImpl(),DBConnection::getConnection);protected void doGet(HttpServletRequest q,HttpServletResponse s)throws ServletException,IOException{try{long id=Long.parseLong(q.getParameter("reservationRoomId"));var page=service.assignmentPage(id);if(page.isEmpty()){s.sendError(404);return;}q.setAttribute("page",page.get());q.getRequestDispatcher("/WEB-INF/views/receptionist/rooms/assign.jsp").forward(q,s);}catch(NumberFormatException e){s.sendError(400,"Reservation room ID không hợp lệ.");}catch(DataAccessException e){getServletContext().log("Room selection failed",e);s.sendError(500);}}protected void doPost(HttpServletRequest q,HttpServletResponse s)throws IOException{s.sendError(405,"Room assignment is committed only during check-in.");}}
